import type { Rect } from '@/core/math';
import type { CameraConfig } from '@/camera/CameraRig';
import type { InteractableDef } from '@/interaction/Interactable';

/**
 * A room, as data. Grows phase by phase (enemies in F7, environment in F8, gates/secrets in F9…) but every
 * addition is OPTIONAL, so a room written today keeps working. Authoring guide: docs/guides/create-room.md.
 *
 * Coordinates: metres, +X right, +Y up, gameplay plane z = 0. Rects are { x0, y0, x1, y1 } with x0 < x1, y0 < y1.
 */

export interface SolidDef {
  /** Unique within the room. Auto-generated by builders when omitted. */
  id: string;
  rect: Rect;
  /** `solid` blocks from all sides; `oneway` is a jump-through platform. */
  kind?: 'solid' | 'oneway';
  /** Visual material preset for the environment builder (`stone`, `earth`, `wood`, `moss`…). */
  material?: string;
  /** Gameplay label (gates and breakables use it to find their collider). */
  tag?: string;
}

export interface EntryDef {
  id: string;
  /** Feet position where the player appears. */
  x: number;
  y: number;
  facing?: 1 | -1;
}

/** An enemy the room places in the world when it is built (data: `RoomRuntime` reads it, docs/ARCHITECTURE-2D.md §5.11). */
export interface SpawnDef {
  /** Unique within the room. */
  id: string;
  /** Id of the `EnemyDefinition` to place. */
  enemy: string;
  /** Feet position. */
  x: number;
  y: number;
  facing?: 1 | -1;
  /**
   * World flag set when this enemy is defeated. While the flag is set the enemy is NOT placed again: the way it guarded
   * stays open through deaths and reloads. Without it, the enemy comes back every time the room is built (§9.2.5).
   */
  defeatFlag?: string;
}

/**
 * A door that is closed until a world flag is set. It is one of the room's `solids`, switched off while open. A gate that is OPEN by default and
 * only shuts for a while — the doors of a boss arena — says so with `closeWhen`: a VOLATILE flag (`~…`) the fight raises and the end of it
 * (or the unloading of the room) drops, which no saved game ever keeps (docs/PROMPT6-LOG.md S29).
 */
export interface GateDef {
  /** Unique within the room. */
  id: string;
  /** Id of the solid (in `solids`) that blocks while the gate is closed. */
  solid: string;
  /** The gate is open while this world flag is set. Omitted: it is open unless `closeWhen` shuts it. */
  openWhen?: string;
  /** The gate is SHUT while this flag is set, whatever `openWhen` says. */
  closeWhen?: string;
}

/** Where a way out leads: a room and one of ITS entries (a spawn point). */
export interface Destination {
  room: string;
  entry: string;
}

/**
 * A way out: touching its zone raises `exit:reached` and, when it has a destination, starts the room transition (fade out,
 * load the destination, put the player at the entry it names, fade in: docs/PROMPT6-LOG.md S23). An exit without `to` only
 * raises the event (the test rooms, and `end`).
 */
export interface ExitDef {
  /** Unique within the room. */
  id: string;
  /** The trigger zone. */
  rect: Rect;
  /** Where it leads: the room and the entry the player appears at (never assumed to be the middle of anything). */
  to?: Destination;
  /** The way out of the WORLD as it stands (the end of the slice): it leads nowhere, so a room of the world may have one exit like this without `to`. */
  end?: boolean;
  /**
   * The way is shut while this world flag is NOT set: the zone does nothing (a door of the world that something has to open).
   * It mirrors the physical gate in the room; the world validator uses it to prove the whole world can be finished.
   */
  requires?: string;
}

/**
 * A part of a room where the camera is held to other limits and, optionally, zoomed (docs/PROMPT6-LOG.md S26): a boss arena that is shut
 * for the fight and free again afterwards, a shaft. Nothing cinematic: the zone only decides which limits the view must stay inside
 * while the hero is in it, and the limits ease in and out (the view never jumps).
 */
export interface CameraZoneDef {
  /** Unique within the room. */
  id: string;
  /** The zone applies while the hero's FEET are inside this rectangle (world metres)… */
  rect: Rect;
  /** …and the view must stay inside THESE limits instead of the room's. */
  bounds: Rect;
  /** The visible height, in metres, while it applies; the room's own when omitted. */
  viewHeight?: number;
  /** It applies only while this world flag is set / clear (an arena that is shut for the fight and free after the guardian falls). */
  whenSet?: string;
  whenClear?: string;
  /** Seconds the limits take to ease into and out of this zone (the rig's own default when omitted). */
  smoothTime?: number;
}

/**
 * A SEAL (docs/PROMPT6-LOG.md S28): a ward of violet ink that holds a way shut until it is hit by the one thing that can break it — a skill,
 * not the sword. It is a neutral target standing in front of the door it holds (the door is an ordinary gate that opens with the flag the
 * seal sets); every attack that is not in `accepts` bounces off it, and the first one that is breaks it for good (the flag stays set
 * through deaths, reloads and saved games, so a broken seal is never built again).
 */
export interface SealDef {
  /** Unique within the room. */
  id: string;
  /** Where it stands (its feet) and how far its vulnerable area reaches each side; the area is `height` tall. */
  x: number;
  y: number;
  halfWidth?: number;
  height?: number;
  /** The attacks (the ids a hit carries: a skill's id, `spirit_bolt`) that break it; anything else is turned away. */
  accepts: readonly string[];
  /** The world flag it sets when it breaks: the gate it holds opens with it. */
  flag: string;
  /**
   * The flag that says the hero HAS what breaks it (the card that teaches the skill). Only for the world validator: it plays the world on
   * paper, and a seal that nobody can break (because the card is behind it) would make the rest of the world unreachable.
   */
  needs?: string;
}

/**
 * A boss (docs/PROMPT6-LOG.md S29): a guardian that waits, dormant, in its arena, wakes when the hero steps into it and fights until it falls
 * or the hero does. The room places it like a spawn — but it is its own list: it carries the arena, the flag it sets for good when it falls
 * (`defeatFlag`: it is never built again, and what waited for it — a door, an exit, a reward — opens) and the VOLATILE flag it raises while
 * the fight lasts (`fightFlag`, `~…`: the doors `closeWhen` it; a defeat of the hero, a reload or a saved game forgets it, so the next
 * visit finds the doors open and the guardian whole).
 */
export interface BossDef {
  /** Unique within the room. */
  id: string;
  /** The guardian (an id of the registry of bosses), where it stands (feet) and which way it faces. */
  guardian: string;
  x: number;
  y: number;
  facing?: 1 | -1;
  /** The fight begins when the hero's FEET are inside this rectangle while the guardian stands. */
  arena: Rect;
  /** World flag set when the guardian falls. */
  defeatFlag: string;
  /** Volatile flag (it starts with `~`) raised while the fight lasts. */
  fightFlag: string;
}

/** What a hazard is. The interface draws it by kind; `spikes` is the one that exists today. */
export type HazardKind = 'spikes';

/**
 * A danger that is part of the room and hurts whoever touches it (docs/PROMPT6-LOG.md S25). It is not an enemy: it has no health, no brain
 * and no telegraph — its zone simply hurts the hero while they stand in it. It hurts through the COMBAT system, so every rule of a hit
 * applies as it is: damage, the knockback away from the zone, stun, hit-stop, the i-frames that follow (a second touch during them does
 * nothing) and the usual events. A pit is not one: falling out of the world is `killY`.
 */
export interface HazardDef {
  /** Unique within the room. */
  id: string;
  kind: HazardKind;
  /** The zone that hurts, world metres. */
  rect: Rect;
  /** Points of life each hit takes (default 1). */
  damage?: number;
}

export interface RoomDefinition {
  id: string;
  regionId: string;
  /** Working name (debug panel, logs). The name the PLAYER reads is `nameKey`, a text key. */
  name: string;
  /** Text key of the localised display name (`room.r1.name`): texts live in the catalogs, never in the content. */
  nameKey?: string;
  /** Room extents; also the default camera bounds. */
  bounds: Rect;
  solids: SolidDef[];
  entries: EntryDef[];
  /** Below this Y the player has fallen out of the world (damage + respawn at the last safe ground). */
  killY?: number;
  /**
   * The camera of this room: its limits (`bounds`: the area the view may show — the room's extents when omitted — so the left, right, top
   * and bottom edges the view never crosses), the zones inside it that hold other limits (the first one the hero is in wins), and any
   * tuning of the rig itself.
   */
  camera?: Partial<CameraConfig> & { bounds?: Rect; zones?: CameraZoneDef[] };
  /** Enemies placed when the room is built. */
  spawns?: SpawnDef[];
  /** Doors that open with world flags. */
  gates?: GateDef[];
  /** Ways out of the room. */
  exits?: ExitDef[];
  /** Things the player can interact with: pickups, levers… (docs/GAME-SPEC-2D.md §12). Rewards write world flags. */
  interactables?: InteractableDef[];
  /** Zones that hurt the hero: spikes (docs/PROMPT6-LOG.md S25). */
  hazards?: HazardDef[];
  /** Wards that only a skill breaks (docs/PROMPT6-LOG.md S28). */
  seals?: SealDef[];
  /** Guardians that fight in an arena (docs/PROMPT6-LOG.md S29). */
  bosses?: BossDef[];
  /** Provisional scenery behind and in front of the action (never collision): `render/backdrops` draws it. */
  art?: { backdrop: string; seed?: number };
}
